int ext4_orphan_add(handle_t *handle, struct inode *inode) {
    int err = 0;
    struct ext4_Orphan *orphan;

    if (!ext4_should_process_orphan(inode->i_sb))
        return 0;

    mutex_lock(&EXT4_I(inode)->i_orphan_lock);

    if (list_empty(&EXT4_I(inode)->i_orphan)) {
        if (!S_ISREG(inode->i_mode) && !S_ISDIR(inode->i_mode) &&
            !S_ISLNK(inode->i_mode)) {
            mutex_unlock(&EXT4_I(inode)->i_orphan_lock);
            return -EINVAL;
        }

        err = ext4_journal_get_write_access(handle, inode->i_sb,
                                              EXT4_SB(inode->i_sb)->s_sbh);
        if (err)
            goto out;

        err = ext4_reserve_inode(handle, inode);
        if (err)
            goto out;

        ext4_update_orphan_list(inode->i_sb, inode->i_ino);

        err = ext4_mark_inode_dirty(handle, inode);
        if (err)
            goto out;
    }

    list_add_tail(&EXT4_I(inode)->i_orphan,
                  &EXT4_SB(inode->i_sb)->s_orphan);
out:
    mutex_unlock(&EXT4_I(inode)->i_orphan_lock);
    return err;
}

int ext4_add_to_orphan_list(handle_t *handle, struct inode *inode)
{
    int ret = 0;
    struct super_block *sb = inode->i_sb;
    struct ext4_sb_info *sbi = EXT4_SB(sb);
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_orphan *orphan;

    if (EXT4_HAS_INCOMPAT_FEATURE(sb, EXT4_FEATURE_INCOMPAT_ORPHAN_FILE))
        return 0;

    if (inode->i_nlink == 0)
        return 0;

    if (!S_ISREG(inode->i_mode) && !S_ISDIR(inode->i_mode) && !S_ISLNK(inode->i_mode))
        return -EINVAL;

    mutex_lock(&sbi->s_orphan_lock);

    if (ei->i_orphan) {
        mutex_unlock(&sbi->s_orphan_lock);
        return -EBUSY;
    }

    ret = ext4_journal_get_write_access(handle, inode->i_sb, NULL);
    if (ret < 0)
        goto unlock;

    ret = ext4_journal_space_reservable(inode, EXT4_JOURNAL_SPACE_RESERVED_ORPHAN);
    if (ret < 0)
        goto unlock;

    orphan = kmalloc(sizeof(*orphan), GFP_NOFS);
    if (!orphan) {
        ret = -ENOMEM;
        goto unlock;
    }

    orphan->i_ino = inode->i_ino;
    orphan->i_next = sbi->s_orphan;
    sbi->s_orphan = orphan;

    ei->i_orphan = orphan;

    mark_inode_dirty(inode);

unlock:
    mutex_unlock(&sbi->s_orphan_lock);
    return ret;
}

int ext4_orphan_add(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan *orphan;
    int ret = 0;

    if (!ext4_should_orphan(inode))
        return 0;

    if (!S_ISREG(inode->i_mode) && !S_ISDIR(inode->i_mode) &&
        !S_ISLNK(inode->i_mode))
        return 0;

    mutex_lock(&sbi->s_orphan_lock);

    if (ei->i_orphan) {
        mutex_unlock(&sbi->s_orphan_lock);
        return 0;
    }

    ret = ext4_journal_get_write_access(handle, inode->i_sb->s_journal,
                                        &EXT4_I(inode)->i_bh, 0);
    if (ret) {
        mutex_unlock(&sbi->s_orphan_lock);
        return ret;
    }

    ret = ext4_journal_space_needed(handle, EXT4_JOURNAL_SPACE_RESERVED);
    if (ret) {
        mutex_unlock(&sbi->s_orphan_lock);
        return ret;
    }

    if (sbi->s_orphan) {
        orphan = kzalloc(sizeof(struct ext4_orphan), GFP_NOFS);
        if (!orphan) {
            mutex_unlock(&sbi->s_orphan_lock);
            return -ENOMEM;
        }
        orphan->ino = inode->i_ino;
        list_add(&orphan->list, &sbi->s_orphan_list);
        ei->i_orphan = orphan;
    }

    ext4_set_inode_flag(inode, EXT4_INODE_ORPHAN_FILE);
    mark_inode_dirty(inode);

    mutex_unlock(&sbi->s_orphan_lock);
    return ret;
}

int ext4_add_orphan(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct list_head *orphan_list = &sbi->s_orphan;
    int err = 0;

    if (!EXT4_HAS_INCOMPAT_FEATURE(inode->i_sb, EXT4_FEATURE_INCOMPAT_ORPHAN_FILE))
        return -EINVAL;

    mutex_lock(&sbi->s_orphan_lock);

    if (!list_empty(&ei->i_list)) {
        mutex_unlock(&sbi->s_orphan_lock);
        return -EBUSY;
    }

    if ((S_ISREG(inode->i_mode) || S_ISDIR(inode->i_mode) || S_ISLNK(inode->i_mode)) == 0) {
        mutex_unlock(&sbi->s_orphan_lock);
        return -EINVAL;
    }

    err = ext4_journal_get_write_access(handle, inode->i_sb->s_journal, inode->i_ino, 0);
    if (err) {
        mutex_unlock(&sbi->s_orphan_lock);
        return err;
    }

    err = ext4_handle_dirty_metadata(handle, NULL, inode);
    if (err) {
        mutex_unlock(&sbi->s_orphan_lock);
        return err;
    }

    if (sbi->s_desc_per_block == 0)
        sbi->s_desc_per_block = 1;

    if (!ext4_has_feature_orphan(inode->i_sb)) {
        mutex_unlock(&sbi->s_orphan_lock);
        return -EINVAL;
    }

    ei->i_dtime = 0;
    list_add_tail(&ei->i_list, orphan_list);

    mutex_unlock(&sbi->s_orphan_lock);
    return err;
}

int ext4_orphan_add(handle_t *handle, struct inode *inode)
{
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_super_block *es;
    struct ext4_sb_info *sbi;
    struct list_head *head;
    int err;

    if (!ext4_handle_valid(handle))
        return -EINVAL;

    sbi = EXT4_SB(inode->i_sb);
    es = &(sbi->s_es);

    spin_lock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
    head = &EXT4_SB(inode->i_sb)->s_orphan;

    if (!S_ISREG(inode->i_mode) && !S_ISDIR(inode->i_mode) &&
        !S_ISLNK(inode->i_mode)) {
        spin_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
        return -EINVAL;
    }

    if (!list_empty(&ei->i_orphan)) {
        spin_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
        return 0;
    }

    err = ext4_journal_get_write_access(handle, inode->i_sb, NULL);
    if (err) {
        spin_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
        return err;
    }

    if (es->s_last_orphan == 0) {
        es->s_last_orphan = cpu_to_new32(inode->i_ino);
        err = ext4_handle_dirty_super(handle, inode->i_sb);
        if (err) {
            spin_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
            return err;
        }
    }

    list_add_tail(&ei->i_orphan, head);
    spin_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);

    return 0;
}
